// Text Encoding Exception: Vietnamese labels from the real brief-panel UI.
// Local independent UI probe: no worker test or helper imports. Synthetic adapters only.
import { beforeEach, afterEach, describe, it, expect, vi } from 'vitest';
import { fireEvent, render, screen, waitFor } from '@testing-library/react';
import { DynamicForm } from '@/components/DynamicForm';
import type { Template } from '@/types';

vi.mock('@/lib/i18n', () => ({ useLanguage: () => ({ language: 'en', t: (key: string) => key }) }));
vi.mock('@/components/Settings', () => ({ useSettings: () => ({ settings: { preferences: { defaultExportMode: 'simple' } }, isLoaded: true }) }));
vi.mock('@/components/UserContext', () => ({ useUserContext: () => ({ getContextPrompt: () => '' }) }));
vi.mock('@/lib/skill-template-map', () => ({ getSkillForTemplate: () => null }));
vi.mock('@/components/WorkflowVisualizer', () => ({ WorkflowVisualizer: () => null }));
// This fixed result makes an unrelated handoff affordance render; it is not governance proof.
vi.mock('@/lib/enforcement', () => ({ evaluateEnforcement: () => ({ status: 'ALLOW', reasons: [], specGate: { status: 'PASS', missing: [] } }) }));
vi.mock('@/lib/enforcement-log', () => ({ logEnforcementDecision: () => undefined }));

const fixture: Template = {
    id: 'local-brief-cycle-probe', name: 'Local brief cycle', description: 'Synthetic presentation probe',
    icon: 'L', category: 'business', difficulty: 'easy', intentPattern: 'Describe [goal] using [notes].',
    outputExpected: ['Brief'], fields: [
        { id: 'goal', type: 'text', label: 'Local goal', placeholder: 'Local goal marker', required: true },
        { id: 'notes', type: 'textarea', label: 'Local notes', placeholder: 'Local notes marker', required: true },
    ],
};
const downloads: Blob[] = [];
const clipboard = vi.fn(async () => undefined);
const send = vi.fn();
const execute = vi.fn();
const status = () => screen.getByRole('status', { name: 'Trạng thái ý tưởng' });
const openPrimary = () => fireEvent.click(screen.getByRole('button', { name: /Create Agent Spec/ }));
const toggle = () => fireEvent.click(screen.getByRole('button', { name: /Export Spec/ }));
const preview = () => screen.getByRole('region', { name: 'English Working Brief' }).querySelector('pre')?.textContent;
const readBlob = (blob: Blob) => new Promise<string>((resolve, reject) => {
    const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = reject; reader.readAsText(blob);
});

beforeEach(() => {
    downloads.length = 0; send.mockReset(); execute.mockReset(); clipboard.mockClear();
    vi.stubGlobal('fetch', vi.fn(() => { throw new Error('Local probe forbids all network destinations'); }));
    vi.stubGlobal('URL', Object.assign(class extends URL {}, {
        createObjectURL: vi.fn((blob: Blob) => { downloads.push(blob); return 'blob:local-probe'; }),
        revokeObjectURL: vi.fn(),
    }));
    vi.spyOn(HTMLAnchorElement.prototype, 'click').mockImplementation(() => undefined);
    Object.defineProperty(navigator, 'clipboard', { configurable: true, value: { writeText: clipboard } });
});
afterEach(() => { vi.restoreAllMocks(); vi.unstubAllGlobals(); });

describe('Local independent voluntary-close and hidden revision sequence', () => {
    it('retains same-idea output, rejects hidden A-B-A resurrection, and resets the successful handoff/template lifetime', async () => {
        const props = { template: fixture, initialValues: { goal: 'LOCAL-GOAL-41', notes: 'LOCAL-NOTE-A-41' }, onSubmit: execute, onBack: vi.fn(), onSendToAgent: send };
        const view = render(<DynamicForm key="first" {...props} />);
        expect(screen.queryByRole('status', { name: 'Trạng thái ý tưởng' })).toBeNull();
        expect(downloads).toHaveLength(0);
        openPrimary();
        expect(status().textContent).toContain('Chưa xác nhận ý tưởng');
        fireEvent.click(screen.getByRole('button', { name: 'Xác nhận ý tưởng và xuất cho agent' }));
        const first = await readBlob(downloads[0]);
        fireEvent.click(screen.getByRole('button', { name: 'Xem English Working Brief (tùy chọn)' }));
        expect(preview()).toBe(first);

        fireEvent.click(screen.getByRole('button', { name: 'Đóng phần xuất brief' }));
        expect(screen.queryByRole('status', { name: 'Trạng thái ý tưởng' })).toBeNull();
        expect(screen.queryByRole('button', { name: 'Sao chép Working Brief' })).toBeNull();
        toggle();
        expect(status().textContent).toContain('Phiên bản ý tưởng 1 · Đã xác nhận ý tưởng');
        expect(preview()).toBe(first);
        expect(downloads).toHaveLength(1);
        expect(clipboard).not.toHaveBeenCalled(); expect(send).not.toHaveBeenCalled(); expect(execute).not.toHaveBeenCalled();

        toggle();
        fireEvent.change(screen.getByPlaceholderText('Local notes marker'), { target: { value: 'LOCAL-NOTE-B-42' } });
        fireEvent.change(screen.getByPlaceholderText('Local notes marker'), { target: { value: 'LOCAL-NOTE-A-41' } });
        openPrimary();
        await waitFor(() => expect(status().textContent).toContain('Phiên bản ý tưởng 3 · Chưa xác nhận ý tưởng'));
        expect(preview()).toBeUndefined();
        expect((screen.getByRole('button', { name: 'Sao chép Working Brief' }) as HTMLButtonElement).disabled).toBe(true);
        expect((screen.getByRole('button', { name: 'Gửi Working Brief cho Agent INTAKE' }) as HTMLButtonElement).disabled).toBe(true);
        expect(downloads).toHaveLength(1);
        fireEvent.click(screen.getByRole('button', { name: 'Xác nhận ý tưởng và xuất cho agent' }));
        const current = await readBlob(downloads[1]);
        expect(current).toContain('Idea revision: 3'); expect(current).not.toBe(first);
        fireEvent.click(screen.getByRole('button', { name: 'Gửi Working Brief cho Agent INTAKE' }));
        expect(send).toHaveBeenCalledTimes(1); expect(send).toHaveBeenLastCalledWith(current);
        expect(screen.queryByRole('status', { name: 'Trạng thái ý tưởng' })).toBeNull();
        toggle();
        expect(status().textContent).toContain('Phiên bản ý tưởng 1 · Chưa xác nhận ý tưởng');
        expect(downloads).toHaveLength(2);

        view.rerender(<DynamicForm key="second" {...props} template={{ ...fixture, id: 'local-replaced-template' }} />);
        expect(screen.queryByRole('status', { name: 'Trạng thái ý tưởng' })).toBeNull();
        openPrimary(); expect(status().textContent).toContain('Phiên bản ý tưởng 1 · Chưa xác nhận ý tưởng');
        expect(downloads).toHaveLength(2); expect(execute).not.toHaveBeenCalled(); expect(globalThis.fetch).not.toHaveBeenCalled();
    });
});
